# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_137'] || []

control 'CKV_AWS_137' do
  title 'Ensure that Elasticsearch is configured inside a VPC'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_elasticsearch_domain resources that actually exist, read through
    the stock inspec-aws aws_elasticsearchservice_domain resource.
  DESC

  desc 'rationale', <<~RATIONALE
    A domain outside a VPC has a public endpoint whose only barrier is its
    access policy, so a mistake in that document exposes the index to the
    internet. Inside a VPC the security group and route table bound
    reachability before the policy is consulted at all.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_elasticsearch_domain: vpc_options is CKV_ANY;
    aws_opensearch_domain: vpc_options is CKV_ANY
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_elasticsearch_domain:

      resource "aws_elasticsearch_domain" "search" {
        domain_name           = "search"
        elasticsearch_version = "7.10"

        vpc_options {
          subnet_ids         = var.private_subnet_ids
          security_group_ids = [aws_security_group.search.id]
        }
      }

    Note (aws_elasticsearch_domain): There is no in-place fix. A domain is
    created either public or VPC-bound and cannot be moved between the two;
    closing this finding means creating a VPC domain, reindexing into it and
    retiring the public one.

    Terraform — aws_opensearch_domain:

      resource "aws_opensearch_domain" "search" {
        domain_name    = "search"
        engine_version = "OpenSearch_2.11"

        vpc_options {
          subnet_ids         = var.private_subnet_ids
          security_group_ids = [aws_security_group.search.id]
        }
      }

    Note (aws_opensearch_domain): Same constraint as the Elasticsearch resource:
    public-to-VPC is a migration, not an update.
  FIX

  tag checkov_id:            'CKV_AWS_137'
  tag checkov_category:      'NETWORKING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_elasticsearch_domain aws_opensearch_domain]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/elasticsearch_domain#vpc-options'
  tag nist:                  ['SC-7', 'SC-7 (5)']
  tag nist_r4:               ['SC-7', 'SC-7 (5)']
  tag cci:                   ['CCI-001097', 'CCI-002080']
  tag ksi:                   ['KSI-CNA-NDS']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    aws_elasticsearchservice_domains(aws_region: region).domain_names.to_a.map { |id| [id, region] }
  end

  # A plural resource whose table is built from the API response returns nil for
  # a column that does not exist, rather than raising. Passing that on gives
  # "`[:x]` must be provided" and kills the control. Blank ids are separated out
  # and asserted on below, so a wrong `ids` column is a visible failure rather
  # than a crash or a silent Not Applicable.
  unusable = found.count { |id, _r| "#{id}".strip.empty? }
  found = found.reject { |id, _r| "#{id}".strip.empty? }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_elasticsearch_domain', rules: exempt) }

  if unusable.positive?
    describe "aws_elasticsearch_domain enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `ids` column in resource_map.yml "          'likely names a field this resource does not expose'
      end
    end
  end

  # `unusable.positive?` keeps the control APPLICABLE when every id came back
  # blank. Without it only_if skips the control, and the wrong-column case this
  # guard exists to catch is exactly the case it would suppress — a Not
  # Applicable that means "the enumeration is broken".
  applicable = !in_scope.empty? || unusable.positive?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_elasticsearch_domain in scope') { applicable }

  in_scope.each do |id, region|
    describe aws_elasticsearchservice_domain(domain_name: id, aws_region: region) do
      its('vpc_options.vpc_id') { should satisfy('be set') { |v| !v.nil? && !(v.respond_to?(:empty?) && v.empty?) } }
    end
  end
end
